import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

// 1) 模拟传感器数据源：每 100ms 发射一条（生产者快，约 10 条/秒）
fun sensorFlow(): Flow<Int> = flow {
    var value = 0
    while (true) {
        delay(100)
        println("emit -> $value  [${Thread.currentThread().name}]")
        emit(value++)
    }
}

fun main() = runBlocking {
    val job = launch {
        sensorFlow()
            // 2) 把上游切到 Default 线程池执行（注意：只影响它"前面"的部分）
            .flowOn(Dispatchers.Default)
            // 3) 解耦生产/消费速率：最多积压 8 条，满了上游才挂起
            .buffer(capacity = 8)
            // 4) 下游做一次轻量计算
            .map { it * it }
            // 5) 允许丢弃积压值，只保留最新一条（DROP_OLDEST）
            .conflate()
            // 6) 消费者很慢：约 3.3 条/秒
            .collect { v ->
                delay(300)
                println("collect <- $v  [${Thread.currentThread().name}]")
            }
    }

    delay(1200)
    job.cancelAndJoin()   // 协作式取消：flow 中的 delay 会被打断
    println("done")
}

/*
预期现象（线程名略有差异）：
emit -> 0 ... emit -> 11 大约发射 12 条
但 collect 只看到 0, 25, 100 ... 这样的少数几条（中间值被 conflate 丢弃）
并且 emit 的线程是 DefaultDispatcher-worker，collect 的线程是 main
*/

